package main

import (
	"bufio"
	"fmt"
	"os"
)

// The root of x's group, pointing every node on the way straight at it.
func find(parent []int, x int) int {
	if parent[x] != x {
		parent[x] = find(parent, parent[x])
	}
	return parent[x]
}

func countComponents(n int, edges [][2]int) int {
	parent := make([]int, n)
	for i := range parent {
		parent[i] = i
	}
	components := n
	for _, edge := range edges {
		rootU := find(parent, edge[0])
		rootV := find(parent, edge[1])
		if rootU != rootV {
			parent[rootU] = rootV
			components--
		}
	}
	return components
}

func main() {
	reader := bufio.NewReader(os.Stdin)
	var n, m int
	fmt.Fscan(reader, &n, &m)
	edges := make([][2]int, m)
	for i := range edges {
		fmt.Fscan(reader, &edges[i][0], &edges[i][1])
	}
	fmt.Println(countComponents(n, edges))
}

