import { readFileSync } from "node:fs";

const input = readFileSync(0, "utf8");

// The root of x's group, pointing every node on the way straight at it.
function find(parent: number[], x: number): number {
  const up = parent[x] ?? x;
  if (up === x) {
    return x;
  }
  const root = find(parent, up);
  parent[x] = root;
  return root;
}

function countComponents(n: number, edges: [number, number][]): number {
  const parent = Array.from({ length: n }, (_, i) => i);
  let components = n;
  for (const [u, v] of edges) {
    const rootU = find(parent, u);
    const rootV = find(parent, v);
    if (rootU !== rootV) {
      parent[rootU] = rootV;
      components--;
    }
  }
  return components;
}

